import React, { useEffect } from "react"
import { format } from "date-fns"
import { ServiceTicket } from "../../../hooks/useServiceTickets"
import { Client } from "../../../hooks/useClients"

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

interface ServiceTicketDetailProps {
  ticket: ServiceTicket
  client: Client | null
  onClose: () => void
}

const STATUS_LABELS: Record<string, string> = {
  draft: "Draft",
  confirmed: "Confirmed",
  completed: "Completed",
}

export default function ServiceTicketDetail({
  ticket,
  client,
  onClose,
}: ServiceTicketDetailProps) {
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose()
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [onClose])

  const vehicle = client?.vehicles.find(v => v.vehicleId === ticket.vehicleId)

  return (
    <div
      className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center px-4"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-2xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto"
        onClick={e => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
          <h2 className="font-semibold text-gray-800">Service Ticket</h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-700 text-xl leading-none transition-colors"
            aria-label="Close"
          >
            ✕
          </button>
        </div>

        <div className="px-6 py-5 flex flex-col gap-5">

          {/* Client */}
          <section>
            <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Client</h3>
            <div className="text-sm text-gray-700 space-y-0.5">
              <p className="font-medium text-gray-900">{ticket.clientName}</p>
              {client && (
                <>
                  <p>{client.phone}</p>
                  {client.email && <p>{client.email}</p>}
                </>
              )}
            </div>
          </section>

          {/* Vehicle */}
          <section>
            <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Vehicle</h3>
            {vehicle ? (
              <div className="text-sm text-gray-700 space-y-0.5">
                <p className="font-medium text-gray-900">
                  {vehicle.year} {vehicle.make} {vehicle.model}
                </p>
                {vehicle.color && <p>Color: {vehicle.color}</p>}
                {vehicle.notes && <p className="text-gray-500 italic">{vehicle.notes}</p>}
              </div>
            ) : (
              <p className="text-sm text-gray-400">Vehicle not found</p>
            )}
          </section>

          {/* Service */}
          <section>
            <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Service</h3>
            <div className="text-sm text-gray-700 space-y-0.5">
              <p className="font-medium text-gray-900 capitalize">
                {ticket.serviceTypes.map(s => s === "custom" ? "Custom" : s.replace(/-/g, " ")).join(", ")}
              </p>
              {ticket.customServiceDescription && (
                <p className="text-gray-500">{ticket.customServiceDescription}</p>
              )}
              <p>Quoted price: {fmt(ticket.quotedPrice)}</p>
              <p>Estimated duration: {ticket.estimatedDuration} min</p>
            </div>
          </section>

          {/* Payment */}
          <section>
            <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Payment</h3>
            <div className="bg-gray-50 rounded-lg p-3 text-sm font-mono space-y-1 text-gray-600">
              <div className="flex justify-between">
                <span>Billable amount:</span>
                <span>{fmt(ticket.billableAmount)}</span>
              </div>
              <div className="flex justify-between">
                <span>GST (5%):</span>
                <span>{fmt(ticket.taxGST)}</span>
              </div>
              <div className="flex justify-between">
                <span>QST (9.975%):</span>
                <span>{fmt(ticket.taxQST)}</span>
              </div>
              {ticket.nonBillableAmount > 0 && (
                <div className="flex justify-between">
                  <span>Non-billable:</span>
                  <span>{fmt(ticket.nonBillableAmount)}</span>
                </div>
              )}
              <div className="flex justify-between border-t border-gray-200 pt-1 font-bold text-gray-800">
                <span>Total:</span>
                <span>{fmt(ticket.billableAmount + ticket.taxGST + ticket.taxQST + ticket.nonBillableAmount)}</span>
              </div>
            </div>
          </section>

          {/* Status */}
          <section>
            <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Status</h3>
            <div className="text-sm text-gray-700 space-y-0.5">
              <p>Ticket status: <span className="font-medium">{STATUS_LABELS[ticket.status] ?? ticket.status}</span></p>
              {/* clientConfirmedAt — prepared for Phase 07 */}
            </div>
          </section>

          {/* Meta */}
          <section>
            <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Meta</h3>
            <div className="text-xs text-gray-400 space-y-0.5">
              <p>Created: {format(ticket.createdAt, "MMM d, yyyy 'at' h:mm a")}</p>
              <p>Updated: {format(ticket.updatedAt, "MMM d, yyyy 'at' h:mm a")}</p>
            </div>
          </section>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-100 flex justify-between items-center">
          {/* TODO: Phase 03 edit mode */}
          <button
            disabled
            className="text-sm text-gray-300 cursor-not-allowed"
            title="Edit coming in Phase 03"
          >
            Edit Ticket
          </button>
          <button
            onClick={onClose}
            className="px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium rounded-lg transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  )
}
