import { useState, useEffect } from "react"
import {
  collection,
  onSnapshot,
  addDoc,
  updateDoc,
  doc,
  query,
  orderBy,
  Timestamp,
} from "firebase/firestore"
import { db } from "../firebase/config"

export interface AppointmentRequest {
  id: string
  clientName: string
  phone: string
  email: string
  existingClientId: string | null
  serviceType: string
  customDescription: string
  notes: string
  preferredDates: string[]
  preferredTimeOfDay: "morning" | "afternoon" | "any"
  status: "pending" | "approved" | "rejected"
  createdAt: Date
  reviewedAt: Date | null
  reviewedBy: string | null
}

export interface ApprovePayload {
  date: Date
  timeSlot: string
  serviceType: string
  estimatedDuration: number
  notes: string
  adminEmail: string
}

interface Result {
  requests: AppointmentRequest[]
  pendingCount: number
  loading: boolean
  approveRequest: (id: string, payload: ApprovePayload) => Promise<void>
  rejectRequest: (id: string, adminEmail: string) => Promise<void>
}

function toRequest(id: string, data: Record<string, unknown>): AppointmentRequest {
  return {
    id,
    clientName: data.clientName as string,
    phone: data.phone as string,
    email: (data.email as string) ?? "",
    existingClientId: (data.existingClientId as string | null) ?? null,
    serviceType: data.serviceType as string,
    customDescription: (data.customDescription as string) ?? "",
    notes: (data.notes as string) ?? "",
    preferredDates: (data.preferredDates as string[]) ?? [],
    preferredTimeOfDay: (data.preferredTimeOfDay as AppointmentRequest["preferredTimeOfDay"]) ?? "any",
    status: data.status as AppointmentRequest["status"],
    createdAt: (data.createdAt as Timestamp).toDate(),
    reviewedAt: data.reviewedAt ? (data.reviewedAt as Timestamp).toDate() : null,
    reviewedBy: (data.reviewedBy as string | null) ?? null,
  }
}

export function useAppointmentRequests(): Result {
  const [requests, setRequests] = useState<AppointmentRequest[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!db) { setLoading(false); return }
    const q = query(collection(db, "appointmentRequests"), orderBy("createdAt", "desc"))
    const unsub = onSnapshot(q, snap => {
      setRequests(snap.docs.map(d => toRequest(d.id, d.data() as Record<string, unknown>)))
      setLoading(false)
    })
    return unsub
  }, [])

  const pendingCount = requests.filter(r => r.status === "pending").length

  async function approveRequest(id: string, payload: ApprovePayload): Promise<void> {
    if (!db) throw new Error("Firestore not initialized")
    const req = requests.find(r => r.id === id)
    if (!req) throw new Error("Request not found")

    // Create the appointment
    const now = Timestamp.now()
    await addDoc(collection(db, "appointments"), {
      clientId: req.existingClientId ?? "",
      clientName: req.clientName,
      date: Timestamp.fromDate(payload.date),
      timeSlot: payload.timeSlot,
      status: "confirmed",
      serviceType: payload.serviceType,
      estimatedDuration: payload.estimatedDuration,
      notes: payload.notes,
      clientConfirmedAt: null,
      clientCancelledAt: null,
      createdAt: now,
      updatedAt: now,
    })

    // Mark request as approved
    await updateDoc(doc(db, "appointmentRequests", id), {
      status: "approved",
      reviewedAt: now,
      reviewedBy: payload.adminEmail,
    })
  }

  async function rejectRequest(id: string, adminEmail: string): Promise<void> {
    if (!db) throw new Error("Firestore not initialized")
    await updateDoc(doc(db, "appointmentRequests", id), {
      status: "rejected",
      reviewedAt: Timestamp.now(),
      reviewedBy: adminEmail,
    })
  }

  return { requests, pendingCount, loading, approveRequest, rejectRequest }
}
